import Foundation

// MARK: - Journey Content: The Armor of Grace
/// 30-day journey putting on the full armor of God through biblical womanhood (Free journey)
extension JourneyDay {
    static let armorOfGraceDays: [JourneyDay] = [
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 1,
            title: "Strong in the Lord",
            scripture: "Finally, be strong in the Lord and in his mighty power.",
            scriptureReference: "Ephesians 6:10",
            reflection: "The call to be strong isn't a call to hustle harder or white-knuckle your way through life. It's a call to draw your strength from God — His power, not yours. As a woman of God, your strength is gentle and fierce at the same time. It flows from surrender, not striving.",
            prompt: "Where have you been trying to be strong in your own power? What would it look like to lean into God's strength instead?",
            actionStep: "Identify one area where you're exhausted from striving. Consciously hand it to God today and ask for His strength.",
            prayer: "Lord, I confess I've been running on my own strength and it's running out. Today I choose to be strong in You — not in my abilities, my plans, or my willpower. Fill me with Your mighty power. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 2,
            title: "Put On the Full Armor",
            scripture: "Put on the full armor of God, so that you can take your stand against the devil's schemes.",
            scriptureReference: "Ephesians 6:11",
            reflection: "The armor isn't optional. It's not for extreme situations only. Every day, the enemy has schemes designed to pull you off course — through comparison, fear, busyness, and subtle lies about who you are. Putting on God's armor is a daily, intentional choice.",
            prompt: "What 'schemes' has the enemy been using against you lately? Comparison? Fear? Distraction? Name them honestly.",
            actionStep: "Create a morning ritual: before you check your phone, spend 2 minutes asking God to arm you for the day.",
            prayer: "Father, open my eyes to the enemy's schemes. I choose to put on Your full armor today — every piece, every day. I will not be caught unguarded. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 3,
            title: "Our Real Enemy",
            scripture: "For our struggle is not against flesh and blood, but against the rulers, against the authorities, against the powers of this dark world.",
            scriptureReference: "Ephesians 6:12",
            reflection: "That difficult person, that frustrating situation, that relentless inner critic — they're not the real enemy. There's a spiritual battle behind every struggle. When you see people as the enemy, you fight the wrong fight. When you see the true battle, everything changes.",
            prompt: "Who or what have you been treating as the enemy? How does recognizing the real spiritual battle change your perspective?",
            actionStep: "The next time you feel frustrated with someone today, pause and pray for them instead. Fight the real battle on your knees.",
            prayer: "Lord, give me spiritual eyes to see the real battle. When I'm tempted to fight against people, remind me that my struggle is spiritual. Help me fight with prayer, not anger. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 4,
            title: "Stand Your Ground",
            scripture: "Therefore put on the full armor of God, so that when the day of evil comes, you may be able to stand your ground, and after you have done everything, to stand.",
            scriptureReference: "Ephesians 6:13",
            reflection: "Standing your ground doesn't mean fighting aggressively. It means refusing to be moved. When the storm comes — and it will — you don't run, you don't retreat, you don't crumble. You stand. Rooted. Anchored. Unmoved. That's the quiet power of a woman dressed in God's armor.",
            prompt: "Where do you need to 'stand your ground' right now? In a conviction? A boundary? Your identity?",
            actionStep: "Identify one area where you've been slowly retreating from truth. Take one step back toward standing firm today.",
            prayer: "Father, give me the backbone of grace. When evil comes — and it will — help me stand my ground with quiet, fierce, faith-filled strength. I will not be moved. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 5,
            title: "The Belt of Truth",
            scripture: "Stand firm then, with the belt of truth buckled around your waist.",
            scriptureReference: "Ephesians 6:14a",
            reflection: "In ancient armor, the belt held everything together. Without it, the sword would fall, the breastplate would shift, the tunic would tangle your legs. Truth is what holds your whole spiritual life together. When you believe lies about yourself, God, or others — everything starts to fall apart.",
            prompt: "What lie have you been living under — about your worth, your calling, your relationships? What is God's truth to replace it?",
            actionStep: "Write down one lie and one truth on a card. Carry it with you today. Every time the lie surfaces, read the truth aloud.",
            prayer: "God of truth, buckle me with Your Word today. When lies try to unravel me, hold me together with what is true. I reject every lie of the enemy and choose Your truth. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 6,
            title: "The Breastplate of Righteousness",
            scripture: "With the breastplate of righteousness in place.",
            scriptureReference: "Ephesians 6:14b",
            reflection: "The breastplate protects your heart — the most vulnerable part of you. And notice: it's Christ's righteousness, not yours. You don't earn heart protection through good behavior. You receive it through faith. When condemnation, guilt, and shame come for your heart, His righteousness is your shield.",
            prompt: "Where does shame or condemnation try to wound your heart? How does Christ's righteousness protect you from those attacks?",
            actionStep: "When guilt or shame surfaces today, place your hand on your heart and say: 'My heart is guarded by Christ's righteousness.'",
            prayer: "Jesus, I cannot earn righteousness, but I receive Yours gratefully. Guard my heart today. When condemnation attacks, remind me that I am righteous in You — not by works, but by faith. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 7,
            title: "Feet of Peace",
            scripture: "And with your feet fitted with the readiness that comes from the gospel of peace.",
            scriptureReference: "Ephesians 6:15",
            reflection: "Your feet determine where you go and how you get there. When they're fitted with the gospel of peace, every step you take carries peace into a chaotic world. As a woman of God, you are a peace-bringer — to your home, your relationships, your workplace, your community.",
            prompt: "Where is chaos, conflict, or anxiety ruling your steps? How can you bring the gospel of peace into that space?",
            actionStep: "In your most stressful environment today, consciously choose to be a non-anxious, peace-carrying presence.",
            prayer: "Prince of Peace, fit my feet with Your gospel today. May every step I take carry Your calm, Your truth, and Your hope into a world that desperately needs it. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 8,
            title: "The Shield of Faith",
            scripture: "In addition to all this, take up the shield of faith, with which you can extinguish all the flaming arrows of the evil one.",
            scriptureReference: "Ephesians 6:16",
            reflection: "The arrows are real: doubt, fear, comparison, despair, temptation. They come fast and they burn. But faith — even small faith — is a shield that extinguishes them all. You don't need perfect faith. You need persistent faith. Keep holding up the shield.",
            prompt: "What flaming arrows are you facing right now? Doubt? Fear? Temptation? How can faith — even imperfect faith — be your shield?",
            actionStep: "Write 'FAITH' on your hand today as a physical reminder. When arrows fly, look at your hand and choose to trust God.",
            prayer: "Father, I raise my shield of faith today. The arrows are coming, but my faith is bigger. Not because my faith is perfect, but because my God is. Extinguish every attack with Your power. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 9,
            title: "The Helmet of Salvation",
            scripture: "Take the helmet of salvation.",
            scriptureReference: "Ephesians 6:17a",
            reflection: "The helmet protects your mind — the battlefield where most attacks happen. The enemy's primary strategy is to mess with your thinking: 'You're not enough. God doesn't care. This will never change. You're too far gone.' But salvation secures your mind. You are saved. It is finished. Your mind is protected.",
            prompt: "What thoughts have been attacking you recently? How does the security of your salvation answer those thoughts?",
            actionStep: "Practice 2 Corinthians 10:5 today: Take every thought captive. When a negative thought arises, capture it and replace it with truth.",
            prayer: "Lord, protect my mind today. When anxious, defeating, or despairing thoughts attack, anchor my thinking in the reality of my salvation. I am saved, secure, and free. Amen."
        ),
        JourneyDay(
            journeyID: "armor_of_grace",
            dayNumber: 10,
            title: "The Sword of the Spirit",
            scripture: "And the sword of the Spirit, which is the word of God.",
            scriptureReference: "Ephesians 6:17b",
            reflection: "Every other piece of armor is defensive — the sword is your only offensive weapon. And it's not a physical sword. It's the Word of God. Jesus Himself used Scripture to defeat the enemy in the wilderness. When the enemy speaks, you answer with 'It is written.' Know your sword. Wield it well.",
            prompt: "How familiar are you with your sword? Do you know God's Word well enough to wield it when the enemy attacks?",
            actionStep: "Memorize one verse today that directly counters your biggest current struggle. Use it as your sword this week.",
            prayer: "Holy Spirit, sharpen me with Your Word. Help me know it, love it, and wield it with skill and confidence. When the enemy attacks, give me the right verse at the right time. Amen."
        ),
        // Days 11-30 shorter entries
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 11, title: "Praying at All Times", scripture: "And pray in the Spirit on all occasions with all kinds of prayers and requests.", scriptureReference: "Ephesians 6:18", reflection: "Prayer is the power source behind every piece of armor. Without it, you're wearing armor without strength.", prompt: "How can you weave prayer into every part of your day, not just morning and evening?", actionStep: "Set three prayer reminders throughout your day. Pray for 2 minutes each time.", prayer: "Spirit, teach me to pray without ceasing — in joy, in pain, in the mundane, in the extraordinary. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 12, title: "Alertness and Perseverance", scripture: "With this in mind, be alert and always keep on praying for all the Lord's people.", scriptureReference: "Ephesians 6:18b", reflection: "A warrior stays alert. She watches, she prays, she doesn't let her guard down. Perseverance in prayer is a weapon.", prompt: "Where have you let your guard down spiritually? What needs your prayerful attention?", actionStep: "Pray specifically for three people today — by name, with intention.", prayer: "Lord, keep me alert and persevering. I won't let my guard down. I will keep praying. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 13, title: "Battling Comparison", scripture: "Let us not become conceited, provoking and envying each other.", scriptureReference: "Galatians 5:26", reflection: "Comparison is one of the enemy's most effective arrows against women. It steals joy, breeds resentment, and blinds you to your own calling.", prompt: "Who are you comparing yourself to? What would freedom from that comparison look like?", actionStep: "When comparison strikes today, immediately thank God for one gift He's given you.", prayer: "Lord, free me from the trap of comparison. Help me celebrate others without diminishing myself. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 14, title: "Battling Perfectionism", scripture: "My grace is sufficient for you, for my power is made perfect in weakness.", scriptureReference: "2 Corinthians 12:9", reflection: "Perfectionism masquerades as excellence but is really fear in disguise. God's grace is sufficient in your weakness.", prompt: "Where is perfectionism stealing your peace? What would 'good enough in God's grace' look like?", actionStep: "Do one thing imperfectly today — on purpose. Let grace fill the gap.", prayer: "Jesus, Your grace is enough. Help me release perfectionism and rest in Your sufficient grace. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 15, title: "Battling Fear", scripture: "For God has not given us a spirit of fear, but of power and love and self-control.", scriptureReference: "2 Timothy 1:7", reflection: "Fear is not from God. Every fear-based thought, decision, or pattern is an arrow from the enemy.", prompt: "What fear is holding you back from God's best for your life?", actionStep: "Do one thing today that fear has been preventing you from doing.", prayer: "Father, I reject the spirit of fear. I receive Your power, Your love, and Your self-control. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 16, title: "Battling People-Pleasing", scripture: "Am I now trying to win the approval of human beings, or of God?", scriptureReference: "Galatians 1:10", reflection: "People-pleasing is an identity issue. When you know Whose you are, you stop needing everyone's approval.", prompt: "Whose approval are you chasing? What would it look like to live for an audience of One?", actionStep: "Say 'no' to one thing today that you would normally say 'yes' to out of obligation.", prayer: "Lord, free me from the chains of people-pleasing. I live for Your approval alone. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 17, title: "Battling Busyness", scripture: "Be still, and know that I am God.", scriptureReference: "Psalm 46:10", reflection: "Busyness is the enemy's strategy to keep you too distracted to hear God's voice.", prompt: "What busyness is drowning out God's still, small voice in your life?", actionStep: "Create 15 minutes of intentional stillness today. No phone, no tasks — just be.", prayer: "Lord, still my restless heart. Help me choose presence over productivity. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 18, title: "Battling Anxiety", scripture: "Cast all your anxiety on him because he cares for you.", scriptureReference: "1 Peter 5:7", reflection: "Casting anxiety isn't a one-time event — it's a repeated, trusting surrender.", prompt: "What anxiety are you white-knuckling instead of casting on God?", actionStep: "Write your anxieties on paper and physically place them in your Bible as a symbol of casting them on God.", prayer: "Father, I cast my anxiety on You — not because I'm strong, but because You care for me. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 19, title: "Battling Unworthiness", scripture: "See what great love the Father has lavished on us, that we should be called children of God!", scriptureReference: "1 John 3:1", reflection: "Unworthiness says you don't deserve God's love. Grace says you never did — and He gave it anyway.", prompt: "What makes you feel unworthy of God's love? How does His lavish love answer that?", actionStep: "Speak aloud 5 times today: 'I am a child of God. His love is lavished on me.'", prayer: "Father, silence the voice of unworthiness. I receive Your lavish, undeserved, all-sufficient love. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 20, title: "Battling Control", scripture: "Trust in the Lord with all your heart and lean not on your own understanding.", scriptureReference: "Proverbs 3:5", reflection: "Control is fear wearing a productive mask. Surrender is the bravest thing a woman of faith can do.", prompt: "What are you gripping too tightly? What would surrender look like?", actionStep: "Open your hands, palms up, and pray: 'Lord, I release my grip. I trust You.'", prayer: "Lord, I release control. Your plans are better than mine. I trust You completely. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 21, title: "The Armor of Light", scripture: "Let us put aside the deeds of darkness and put on the armor of light.", scriptureReference: "Romans 13:12", reflection: "God's armor isn't just protection — it's light. You shine when you wear it.", prompt: "How does your armored life shine light into the darkness around you?", actionStep: "Be intentionally light-bearing in one dark situation today.", prayer: "Lord, clothe me in light. Let my armored life push back darkness wherever I go. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 22, title: "Spiritual Endurance", scripture: "Let us run with perseverance the race marked out for us, fixing our eyes on Jesus.", scriptureReference: "Hebrews 12:1-2", reflection: "The race requires endurance, not speed. Keep your eyes on Jesus, not your performance.", prompt: "Where are you growing weary? How can fixing your eyes on Jesus renew your endurance?", actionStep: "When weariness hits today, whisper: 'Eyes on Jesus. One step at a time.'", prayer: "Jesus, I fix my eyes on You — not my pace, not my progress, not others' races. Give me endurance. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 23, title: "Fighting with Worship", scripture: "About midnight Paul and Silas were praying and singing hymns to God.", scriptureReference: "Acts 16:25", reflection: "Worship in the midst of battle is one of the most powerful weapons you have.", prompt: "Can you worship God in the middle of your current battle? What would that look like?", actionStep: "Put on a worship song during your hardest moment today and sing — even if you don't feel like it.", prayer: "Lord, I choose to worship You in the battle. My praise is a weapon. Chains break when I sing. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 24, title: "Fighting with Fasting", scripture: "However, this kind does not go out except by prayer and fasting.", scriptureReference: "Matthew 17:21 (NKJV)", reflection: "Some battles require more than words — they require the focused dependence of fasting.", prompt: "Is God calling you to fast from something — food, social media, noise — to break through?", actionStep: "Fast from one thing today (a meal, social media, complaining) and replace that time with prayer.", prayer: "Father, I hunger for breakthrough more than comfort. Strengthen me as I fast and depend on You alone. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 25, title: "Community in Battle", scripture: "Though one may be overpowered, two can defend themselves. A cord of three strands is not quickly broken.", scriptureReference: "Ecclesiastes 4:12", reflection: "You were never meant to fight alone. Sister warriors standing together are a force the enemy fears.", prompt: "Who is fighting alongside you? Who needs you to fight alongside them?", actionStep: "Text or call one sister today and say: 'I'm fighting for you in prayer. We've got this together.'", prayer: "Lord, give me sisters who fight beside me and the courage to stand beside others. Together we are unbreakable. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 26, title: "Victory Is Already Won", scripture: "But thanks be to God! He gives us the victory through our Lord Jesus Christ.", scriptureReference: "1 Corinthians 15:57", reflection: "You're not fighting FOR victory — you're fighting FROM victory. Jesus already won. You're standing in His triumph.", prompt: "How does knowing the battle is already won change how you face today's challenges?", actionStep: "Write 'VICTORY' somewhere visible and let it remind you: the outcome is secured.", prayer: "Jesus, You already won. I fight from Your victory, not toward it. Thank You for triumph. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 27, title: "Weapons of Kindness", scripture: "Do not be overcome by evil, but overcome evil with good.", scriptureReference: "Romans 12:21", reflection: "Kindness is a weapon. Grace disarms the enemy. Love wins battles that aggression never could.", prompt: "Where can you overcome evil with good today — in a relationship, a conflict, your own heart?", actionStep: "Respond to one frustrating situation today with radical, unexpected kindness.", prayer: "Lord, make my kindness a weapon. Help me overcome evil not with retaliation, but with Your goodness. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 28, title: "Rest as Resistance", scripture: "Come to me, all you who are weary and burdened, and I will give you rest.", scriptureReference: "Matthew 11:28", reflection: "In a world that worships productivity, rest is an act of resistance and faith.", prompt: "Where do you need to rest — not as laziness, but as trust in God's sufficiency?", actionStep: "Take one guilt-free rest today. Read, pray, sit in silence, or nap — and call it worship.", prayer: "Jesus, I come to You weary. I receive Your rest — not as earned, but as a gift. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 29, title: "Dressed and Ready", scripture: "Therefore, put on every piece of God's armor so you will be able to resist the enemy in the time of evil.", scriptureReference: "Ephesians 6:13 (NLT)", reflection: "Every piece matters. Don't leave home without your full armor. You are dressed for battle and built for victory.", prompt: "Which piece of armor do you most need to strengthen? How will you build that habit?", actionStep: "Create a daily 'armor up' routine — a 2-minute morning prayer putting on each piece.", prayer: "Father, I put on every piece — truth, righteousness, peace, faith, salvation, and Your Word. I am dressed and ready. Amen."),
        JourneyDay(journeyID: "armor_of_grace", dayNumber: 30, title: "Armored and Blooming", scripture: "Be on your guard; stand firm in the faith; be courageous; be strong. Do everything in love.", scriptureReference: "1 Corinthians 16:13-14", reflection: "You've spent 30 days putting on the armor of grace. You are strong, guarded, firm, courageous — and you do it all in love. That's the beauty of a woman armed by God: she's fierce and tender, brave and graceful, anchored and blooming.", prompt: "How has this journey changed the way you face spiritual battles? What will you carry forward?", actionStep: "Write your battle cry — a personal declaration of who you are as an armored woman of God. Speak it daily.", prayer: "Lord, I am dressed in Your armor and blooming in Your grace. I will stand firm, fight the good fight, and do everything in love. I am Yours — armored and beautiful. Amen.")
    ]
}
